def prior_six_locked_species_source(source):
    for species, pair in RECORDS.items():
        pattern = r"\[SPECIES_" + species + r"\]\s*=\s*\{.*?\n    \},"
        matches = list(re.finditer(pattern, source, re.S))
        assert len(matches) == 1, (species, "protected record count")
        assert matches[0].group() == pair["after"], (species, "unauthorized species-data change")
        source = source[:matches[0].start()] + pair["before"] + source[matches[0].end():]
    return source
